actions.script:
const counted = {open: caseCounts.openCount, overdue: caseCounts.overdueCount, unassigned: caseCounts.unassignedCount}
const queueText = (caseCounts.queueRows || []).length + ' ' + ec.l10n.localize('queues') + ', ' + ec.l10n.localize('now')
for (const measure of measures) if (Object.hasOwn(counted, measure.key))
    Object.assign(measure, {configured: true, valueText: String(counted[measure.key] ?? 0), denominatorText: queueText})

const levels = ec.resource.script('component://mr-boss/service/ironstone/customerservice/Cases.js').execute('slaMeasures', {periodDays: days})
if (levels.configured) for (const measure of measures) if (levels[measure.key])
    Object.assign(measure, levels[measure.key])

const satisfaction = ec.resource.script('component://mr-boss/service/ironstone/customerservice/Feedback.js').execute('csatMeasure', {periodDays: days})
if (satisfaction.configured) for (const measure of measures) if (measure.key === 'csat')
    Object.assign(measure, satisfaction.csat)

if (split) {
    const casesJs = ec.resource.script('component://mr-boss/service/ironstone/customerservice/Cases.js')
    const mine = casesJs.execute('myCounts', {})
    const myLevels = casesJs.execute('slaMeasures', {periodDays: days, myOnly: true})
    const myOf = {open: String(mine.openCount), overdue: String(mine.overdueCount)}
    for (const key of ['slaCompliance', 'firstResponse', 'resolution'])
        if (myLevels.configured && myLevels[key]) myOf[key] = myLevels[key].valueText
    for (const measure of measures) {
        measure.myText = Object.hasOwn(myOf, measure.key) ? myOf[measure.key] : null
        measure.teamText = measure.configured ? measure.valueText : null
    }
}
